package com.yeyamo_mobile.api.partner_service.interfaces.rest;import static com.yeyamo_mobile.api.partner_service.interfaces.rest.ArtisanDtos.*;import com.yeyamo_mobile.api.partner_service.application.ArtisanProfileService;import jakarta.validation.Valid;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController public class ArtisanController{private final ArtisanProfileService service;public ArtisanController(ArtisanProfileService s){service=s;}@PostMapping("/api/v1/partners/me/artisan-profile")@ResponseStatus(HttpStatus.CREATED)public Response create(@RequestBody@Valid Request r,Authentication a,@RequestHeader(value="X-Correlation-ID",required=false)String c){return service.create(a.getName(),r,c);}@GetMapping("/api/v1/partners/me/artisan-profile")public Response me(Authentication a){return service.me(a.getName());}@PutMapping("/api/v1/partners/me/artisan-profile")public Response update(@RequestBody@Valid Request r,Authentication a,@RequestHeader(value="X-Correlation-ID",required=false)String c){return service.update(a.getName(),r,c);}@GetMapping("/api/v1/artisans")public Page<Response> search(@RequestParam(required=false)String countryCode,@RequestParam(required=false)String adminLevel1Id,@RequestParam(required=false)String cityId,@RequestParam(required=false)UUID specialtyId,@RequestParam(required=false)Boolean verified,@RequestParam(required=false)Boolean acceptsCustomOrders,@RequestParam(required=false)Boolean internationalShipping,@RequestParam(required=false)String search,@PageableDefault(size=20,sort="updatedAt",direction=Sort.Direction.DESC)Pageable p){return service.search(countryCode,adminLevel1Id,cityId,specialtyId,verified,acceptsCustomOrders,internationalShipping,search,p);}@GetMapping({"/api/v1/artisans/{id}","/api/v1/artisans/{id}/profile"})public Response publicProfile(@PathVariable UUID id){return service.publicProfile(id);}@GetMapping("/api/v1/artisan-specialties")public List<Specialty>specialties(){return service.specialties();}}
